<script setup>
import { onMounted, onUnmounted } from 'vue'

let animationFrame = null

onMounted(() => {
  const pattern = document.querySelector('.background-pattern')
  if (!pattern) return

  let angle = 0
  const animate = () => {
    angle += 0.5
    pattern.style.backgroundPosition = `${Math.sin(angle * Math.PI / 180) * 50}px ${Math.cos(angle * Math.PI / 180) * 50}px`
    animationFrame = requestAnimationFrame(animate)
  }
  animate()
})

onUnmounted(() => {
  if (animationFrame) {
    cancelAnimationFrame(animationFrame)
  }
})
</script>

